import type { Metadata } from "next";
import { confirmRecipientAction } from "@/app/actions.ts";
import { AppShell } from "@/components/app-shell.tsx";
import { PageHeader } from "@/components/page-header.tsx";
import { SubmitButton } from "@/components/submit-button.tsx";
import { ConfirmOutcome } from "@/features/alerts/confirm-outcome.tsx";
import { isConfirmationToken } from "@/features/alerts/confirm-result.ts";
import { t } from "@/lib/t.ts";

// The route types of `.next/types` are generated by `next typegen`, which this slice does not run; the props are
// written out instead of `PageProps<"/alerts/confirm">`.
interface AlertConfirmPageProps {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}

// The address carries a confirmation token: no request from this page may send it on to another site.
export const metadata: Metadata = { title: t("confirm.title"), referrer: "no-referrer" };

// `/alerts/confirm?token=…` — the link of a confirmation email (slice 06b). Public: whoever got the email opens it
// without a session, so the page reads no session and shows the brand only. Opening it confirms nothing (mail link
// scanners open links by themselves): a person clicks "Confirm email", whose POST carries the token in a hidden
// field to `confirmRecipientAction`. A malformed token gets the invalid sentence and no button. Never logged.
export default async function AlertConfirmPage({ searchParams }: AlertConfirmPageProps) {
  const { token } = await searchParams;
  return (
    <AppShell width="narrow">
      <PageHeader title={t("confirm.title")} />
      {isConfirmationToken(token) ? (
        <form action={confirmRecipientAction} className="flex flex-col gap-4">
          <p data-testid="confirm-lead" className="text-fg-muted">
            {t("confirm.lead")}
          </p>
          <input type="hidden" name="token" value={token} />
          <div>
            <SubmitButton pendingLabel={t("confirm.submitting")} data-testid="confirm-submit">
              {t("confirm.submit")}
            </SubmitButton>
          </div>
        </form>
      ) : (
        <ConfirmOutcome outcome="invalid" />
      )}
    </AppShell>
  );
}
